function uniqueBy(items, keyOf) {
  // Map keys are compared by SameValueZero, so 1 and "1" stay distinct
  // and "__proto__" is an ordinary key.
  const seen = new Map();
  for (const item of items) {
    const key = keyOf(item);
    if (!seen.has(key)) seen.set(key, item);
  }
  return [...seen.values()];
}

module.exports = { uniqueBy };
EOF
cat > test/solution.test.js <<'EOF'
const test = require('node:test');
const assert = require('node:assert');
const { uniqueBy } = require('../src/solution.cjs');

test('keeps first item per key in input order', () => {
  const items = [{ id: 'a', n: 1 }, { id: 'b', n: 2 }, { id: 'a', n: 3 }, { id: 'c', n: 4 }, { id: 'b', n: 5 }];
  assert.deepStrictEqual(uniqueBy(items, (x) => x.id), [items[0], items[1], items[3]]);
});

test('does not mutate input and returns a new array', () => {
  const items = [1, 1, 2];
  const copy = [...items];
  const out = uniqueBy(items, (x) => x);
  assert.deepStrictEqual(items, copy);
  assert.notStrictEqual(out, items);
});

test('distinguishes 1 from "1"', () => {
  assert.deepStrictEqual(uniqueBy([1, '1', 1, '1'], (x) => x), [1, '1']);
});

test('treats "__proto__" as an ordinary key', () => {
  const items = [{ k: '__proto__', v: 1 }, { k: 'other', v: 2 }, { k: '__proto__', v: 3 }];
  assert.deepStrictEqual(uniqueBy(items, (x) => x.k), [items[0], items[1]]);
});

test('empty input returns []', () => {
  assert.deepStrictEqual(uniqueBy([], (x) => x), []);
});
EOF
