import unittest

from solution import parse_port


class ParsePortTests(unittest.TestCase):
    def test_boundaries(self):
        self.assertEqual(parse_port("1"), 1)
        self.assertEqual(parse_port("65535"), 65535)

    def test_out_of_range(self):
        for s in ("0", "65536", "000", "99999999999999999999"):
            with self.assertRaises(ValueError, msg=s):
                parse_port(s)

    def test_spaces_and_leading_zeros(self):
        self.assertEqual(parse_port("  80  "), 80)
        self.assertEqual(parse_port("0008080"), 8080)
        self.assertEqual(parse_port("0000000000065535"), 65535)

    def test_invalid_strings(self):
        for s in ("", "   ", "+80", "-80", "80.0", "8 0", "\t80", "80\n",
                  "\n80", "80\r", "٨٠", "８０", "0x50", "1_000", "abc"):
            with self.assertRaises(ValueError, msg=repr(s)):
                parse_port(s)

    def test_non_strings(self):
        for v in (None, 80, 80.0, b"80", ["80"]):
            with self.assertRaises(ValueError, msg=repr(v)):
                parse_port(v)

    def test_returns_int(self):
        self.assertIs(type(parse_port("443")), int)


if __name__ == "__main__":
    unittest.main()

def parse_port(text):
    """Parse an ASCII decimal port number (1-65535), optionally space-padded."""
    if not isinstance(text, str):
        raise ValueError("port must be a string")
    digits = text.strip(" ")
    if not digits:
        raise ValueError("empty port")
    if not all("0" <= c <= "9" for c in digits):
        raise ValueError(f"invalid port: {text!r}")
    value = int(digits)
    if not 1 <= value <= 65535:
        raise ValueError(f"port out of range: {text!r}")
    return value

import os
import sys
import unittest

sys.path.insert(0, os.path.join(os.path.dirname(__file__), "..", "src"))
from solution import parse_port


class ParsePortTests(unittest.TestCase):
    def test_boundaries(self):
        self.assertEqual(parse_port("1"), 1)
        self.assertEqual(parse_port("65535"), 65535)

    def test_valid_forms(self):
        self.assertEqual(parse_port("  8080  "), 8080)
        self.assertEqual(parse_port("0000080"), 80)
        self.assertIsInstance(parse_port("80"), int)

    def test_out_of_range(self):
        for s in ["0", "000", "65536", "99999999999999999999"]:
            with self.subTest(s=s), self.assertRaises(ValueError):
                parse_port(s)

    def test_invalid(self):
        bad = ["", "   ", "+80", "-1", "\t80", "80\n", "80\t", "\n80",
               "8 0", "80.0", "80.", "٨٠", "８０", "0x50", "1_0", "abc",
               "80 "]
        for s in bad:
            with self.subTest(s=s), self.assertRaises(ValueError):
                parse_port(s)

    def test_non_string(self):
        for v in [None, 80, 80.0, b"80", True, ["80"]]:
            with self.subTest(v=v), self.assertRaises(ValueError):
                parse_port(v)


if __name__ == "__main__":
    unittest.main()

