def merge_intervals(intervals):
    """Merge overlapping or touching closed integer intervals.

    Returns a new sorted list of non-overlapping [start, end] lists.
    The input list and its pairs are not modified.
    Time O(n log n), extra space O(n).
    """
    merged = []
    for start, end in sorted(intervals, key=lambda p: (p[0], p[1])):
        if merged and start <= merged[-1][1]:
            if end > merged[-1][1]:
                merged[-1][1] = end
        else:
            merged.append([start, end])
    return merged
EOF
