from collections import deque


def topological_order(nodes, edges):
    """Return a list containing every node once, with a before b for each edge (a, b).

    Raises ValueError if the graph has a cycle (including self-loops).
    Inputs are not mutated. Time O(V + E), space O(V + E).
    """
    nodes = list(nodes)
    successors = {n: set() for n in nodes}  # sets collapse duplicate edges
    for a, b in edges:
        successors[a].add(b)

    indegree = {n: 0 for n in nodes}
    for outs in successors.values():
        for b in outs:
            indegree[b] += 1

    queue = deque(n for n in nodes if indegree[n] == 0)
    order = []
    while queue:
        n = queue.popleft()
        order.append(n)
        for b in successors[n]:
            indegree[b] -= 1
            if indegree[b] == 0:
                queue.append(b)

    if len(order) != len(nodes):
        raise ValueError("graph contains a cycle")
    return order
