import csv
import io
import re

_AGE_RE = re.compile(r"[0-9]+")


def read_people(text):
    """Parse CSV text with header name,age into a list of dicts.

    Raises ValueError on a wrong header, wrong column counts, invalid CSV
    quoting, or an age that is not ASCII digits within 0..130.
    """
    reader = csv.reader(io.StringIO(text, newline=""), strict=True)
    people = []
    try:
        header = next(reader, None)
        if header != ["name", "age"]:
            raise ValueError(f"invalid header: {header!r}")
        for row in reader:
            if len(row) != 2:
                raise ValueError(f"line {reader.line_num}: expected 2 columns, got {len(row)}")
            name, age = row
            if not _AGE_RE.fullmatch(age):
                raise ValueError(f"line {reader.line_num}: invalid age {age!r}")
            value = int(age)
            if value > 130:
                raise ValueError(f"line {reader.line_num}: age out of range: {value}")
            people.append({"name": name, "age": value})
    except csv.Error as e:
        raise ValueError(f"invalid CSV: {e}") from e
    return people
