'use strict';

const UNSAFE_KEYS = new Set(['__proto__', 'constructor', 'prototype']);

function isPlainObject(value) {
  if (value === null || typeof value !== 'object' || Array.isArray(value)) return false;
  const proto = Object.getPrototypeOf(value);
  return proto === Object.prototype || proto === null;
}

// Deep-copies a JSON-like value, rejecting unsafe keys at any depth.
function clone(value, ancestors) {
  if (value === null || typeof value !== 'object') return value;
  if (ancestors.has(value)) throw new TypeError('Circular structure is not supported');
  const isArray = Array.isArray(value);
  if (!isArray && !isPlainObject(value)) {
    throw new TypeError('Unsupported value: only JSON-like data is allowed');
  }
  ancestors.add(value);
  let out;
  if (isArray) {
    out = value.map((item) => clone(item, ancestors));
  } else {
    out = {};
    for (const key of Object.getOwnPropertyNames(value)) {
      if (UNSAFE_KEYS.has(key)) throw new Error(`Unsafe key rejected: ${key}`);
      Object.defineProperty(out, key, {
        value: clone(value[key], ancestors),
        writable: true,
        enumerable: true,
        configurable: true,
      });
    }
  }
  ancestors.delete(value);
  return out;
}

function mergeConfig(base, override) {
  // Cloning both inputs first validates them fully before any merging,
  // and guarantees the result shares nothing with either input.
  return merge(clone(base, new Set()), clone(override, new Set()));
}

// Operates on already-cloned values, so reusing nodes is alias-safe.
function merge(base, override) {
  if (override === undefined) return base;
  if (isPlainObject(base) && isPlainObject(override)) {
    for (const key of Object.keys(override)) {
      base[key] = key in base ? merge(base[key], override[key]) : override[key];
    }
    return base;
  }
  return override;
}

module.exports = { mergeConfig };
