'use strict';

function splitCents(total, weights) {
  if (!Number.isSafeInteger(total) || total < 0) {
    throw new RangeError('total must be a nonnegative safe integer');
  }
  if (!Array.isArray(weights) || weights.length === 0) {
    throw new RangeError('weights must be a nonempty array');
  }
  let sum = 0;
  for (let i = 0; i < weights.length; i++) {
    const w = weights[i];
    if (!Number.isSafeInteger(w) || w <= 0) {
      throw new RangeError('each weight must be a positive safe integer');
    }
    sum += w;
    if (!Number.isSafeInteger(sum) || !Number.isSafeInteger(total * w)) {
      throw new RangeError('sum or product exceeds the safe integer range');
    }
  }

  // quota_i = total * w_i / sum; compare remainders as exact integers.
  const shares = [];
  const rems = [];
  let allocated = 0;
  for (let i = 0; i < weights.length; i++) {
    const product = total * weights[i];
    const rem = product % sum;
    shares.push((product - rem) / sum);
    rems.push(rem);
    allocated += shares[i];
  }

  const order = rems.map((_, i) => i).sort((a, b) => rems[b] - rems[a] || a - b);
  for (let k = 0, left = total - allocated; k < left; k++) shares[order[k]]++;
  return shares;
}

module.exports = { splitCents };
