'use strict';

function isSafeInt(n) {
  return typeof n === 'number' && Number.isSafeInteger(n);
}

function splitCents(total, weights) {
  if (!isSafeInt(total) || total < 0) {
    throw new RangeError('total must be a nonnegative safe integer');
  }
  if (!Array.isArray(weights) || weights.length === 0) {
    throw new RangeError('weights must be a nonempty array');
  }
  let sum = 0;
  for (let i = 0; i < weights.length; i++) {
    const w = weights[i];
    if (!isSafeInt(w) || w <= 0) {
      throw new RangeError('weights must be positive safe integers');
    }
    sum += w;
    if (!Number.isSafeInteger(sum) || !Number.isSafeInteger(total * w)) {
      throw new RangeError('sum or total*weight exceeds safe integer range');
    }
  }

  const result = new Array(weights.length);
  const remainders = new Array(weights.length);
  let allocated = 0;
  for (let i = 0; i < weights.length; i++) {
    const product = total * weights[i];
    remainders[i] = product % sum; // exact integer; compare as numerators over sum
    result[i] = (product - remainders[i]) / sum;
    allocated += result[i];
  }

  const order = weights.map((_, i) => i);
  order.sort((a, b) => remainders[b] - remainders[a] || a - b);
  for (let k = 0, left = total - allocated; k < left; k++) {
    result[order[k]] += 1;
  }
  return result;
}

module.exports = { splitCents };
