'use strict';

function isNonnegSafeInt(n) {
  return Number.isSafeInteger(n) && n >= 0;
}

function splitCents(total, weights) {
  if (!isNonnegSafeInt(total)) {
    throw new RangeError('total must be a nonnegative safe integer');
  }
  if (!Array.isArray(weights) || weights.length === 0) {
    throw new RangeError('weights must be a nonempty array');
  }
  let sum = 0;
  for (const w of weights) {
    if (!Number.isSafeInteger(w) || w <= 0) {
      throw new RangeError('weights must be positive safe integers');
    }
    sum += w;
    if (!Number.isSafeInteger(sum)) {
      throw new RangeError('sum of weights exceeds safe integer range');
    }
  }

  const result = new Array(weights.length);
  const rems = new Array(weights.length);
  let allocated = 0;
  weights.forEach((w, i) => {
    const product = total * w;
    if (!Number.isSafeInteger(product)) {
      throw new RangeError('total * weight exceeds safe integer range');
    }
    // Integer-exact: % is exact, and (product - rem) is a multiple of sum.
    const rem = product % sum;
    result[i] = (product - rem) / sum;
    rems[i] = rem;
    allocated += result[i];
  });

  const order = weights.map((_, i) => i);
  order.sort((a, b) => rems[b] - rems[a] || a - b);
  const leftover = total - allocated;
  for (let k = 0; k < leftover; k++) result[order[k]] += 1;
  return result;
}

module.exports = { splitCents };
