const VERSION = /^(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)$/;

function parse(v) {
  if (typeof v !== 'string') throw new TypeError('version must be a string');
  const m = VERSION.exec(v);
  if (!m) throw new TypeError('invalid version: ' + v);
  return m.slice(1);
}

function compareVersion(a, b) {
  const pa = parse(a);
  const pb = parse(b);
  for (let i = 0; i < 3; i++) {
    // No leading zeros, so longer means larger; equal length compares lexicographically.
    if (pa[i].length !== pb[i].length) return pa[i].length < pb[i].length ? -1 : 1;
    if (pa[i] !== pb[i]) return pa[i] < pb[i] ? -1 : 1;
  }
  return 0;
}

module.exports = { compareVersion };
