  }
  return [m[1], m[2], m[3]];
}

// Components have no leading zeros, so a longer digit string is larger;
// equal lengths compare correctly lexicographically.
function compareComponent(x, y) {
  if (x.length !== y.length) return x.length < y.length ? -1 : 1;
  if (x === y) return 0;
  return x < y ? -1 : 1;
}

function compareVersion(a, b) {
  const pa = parse(a);
  const pb = parse(b);
  for (let i = 0; i < 3; i++) {
    const c = compareComponent(pa[i], pb[i]);
    if (c !== 0) return c;
  }
  return 0;
