class Emitter {
  constructor() {
    this._listeners = new Map();
  }

  on(event, fn) {
    let set = this._listeners.get(event);
    if (!set) {
      set = new Set();
      this._listeners.set(event, set);
    }
    set.add(fn);
    let active = true;
    return () => {
      if (!active) return;
      active = false;
      this.off(event, fn);
    };
