class Emitter {
  constructor() {
    this._events = new Map(); // event -> Map(fn -> entry)
  }

  on(event, fn) {
    let listeners = this._events.get(event);
    if (!listeners) {
      listeners = new Map();
      this._events.set(event, listeners);
    }
    let entry = listeners.get(fn);
    if (!entry) {
      entry = { fn };
      listeners.set(fn, entry);
    }
    // Only removes the registration it refers to, so a stale handle
    // cannot remove a later re-registration of the same fn.
    return () => {
      const current = this._events.get(event);
      if (current && current.get(fn) === entry) this._remove(event, fn);
    };
  }

  off(event, fn) {
    this._remove(event, fn);
  }

  emit(event, value) {
    const listeners = this._events.get(event);
    if (!listeners) return;
    for (const fn of Array.from(listeners.keys())) fn(value);
  }

  _remove(event, fn) {
    const listeners = this._events.get(event);
    if (!listeners) return;
    listeners.delete(fn);
    if (listeners.size === 0) this._events.delete(event);
  }
}

module.exports = { Emitter };
