'use strict';

class Emitter {
  constructor() {
    // event -> Map(fn -> registration token), in registration order
    this._events = new Map();
  }

  on(event, fn) {
    let listeners = this._events.get(event);
    if (!listeners) {
      listeners = new Map();
      this._events.set(event, listeners);
    }
    // A listener is registered at most once per event.
    const token = listeners.get(fn) || {};
    listeners.set(fn, token);
    let active = true;
    return () => {
      if (!active) return;
      active = false;
      // Only remove if this registration is still the current one.
      const current = this._events.get(event);
      if (current && current.get(fn) === token) this.off(event, fn);
    };
  }

  off(event, fn) {
    const listeners = this._events.get(event);
    if (!listeners) return;
    listeners.delete(fn);
    if (listeners.size === 0) this._events.delete(event);
  }

  emit(event, value) {
    const listeners = this._events.get(event);
    if (!listeners) return;
    for (const fn of Array.from(listeners.keys())) fn(value);
  }
}

module.exports = { Emitter };
EOF
