from pathlib import Path, PureWindowsPath


def resolve_upload(root, supplied):
    """Resolve an untrusted relative path strictly inside root.

    Existing symlinks are followed, so a link pointing outside root is
    rejected. The target may not exist. Nothing is created.
    Raises ValueError for unsafe input.

    NOTE: this is a check-then-use API. It cannot prevent a symlink race
    (TOCTOU): see the tests/README discussion.
    """
    if not isinstance(supplied, str) or not supplied:
        raise ValueError("path must be a non-empty string")
    if "\0" in supplied:
        raise ValueError("NUL byte in path")

    # Reject absolute paths for both POSIX and Windows flavours.
    if Path(supplied).is_absolute() or PureWindowsPath(supplied).anchor:
        raise ValueError("absolute path not allowed")

    root_resolved = Path(root).resolve(strict=True)
    if not root_resolved.is_dir():
        raise ValueError("root is not a directory")

    # strict=False resolves existing symlinks and also normalises "..";
    # the non-existent tail is appended lexically.
    try:
        target = (root_resolved / supplied).resolve(strict=False)
    except (OSError, RuntimeError) as exc:  # e.g. symlink loop
        raise ValueError(f"cannot resolve path: {exc}") from exc

    if target == root_resolved:
        raise ValueError("target must not be the root itself")
    if root_resolved not in target.parents:
        raise ValueError("path escapes root")
    return target

import os
import sys
import tempfile
import unittest
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parent.parent / "src"))
from solution import resolve_upload  # noqa: E402


class ResolveUploadTests(unittest.TestCase):
    def setUp(self):
        self._tmp = tempfile.TemporaryDirectory()
        self.addCleanup(self._tmp.cleanup)
        base = Path(self._tmp.name).resolve()
        self.root = base / "root"
        self.sibling = base / "root-sibling"  # shares the root name prefix
        self.root.mkdir()
        self.sibling.mkdir()
        (self.sibling / "secret.txt").write_text("x")

    def test_simple_and_nested_nonexistent(self):
        self.assertEqual(resolve_upload(self.root, "a.txt"), self.root / "a.txt")
        self.assertEqual(
            resolve_upload(self.root, "d/e/f.txt"), self.root / "d" / "e" / "f.txt"
        )
        self.assertFalse((self.root / "d").exists())  # nothing created

    def test_inner_dotdot_that_stays_inside(self):
        self.assertEqual(resolve_upload(self.root, "a/../b.txt"), self.root / "b.txt")

    def test_absolute_rejected(self):
        with self.assertRaises(ValueError):
            resolve_upload(self.root, str(self.root / "a.txt"))

    def test_root_itself_rejected(self):
        for s in (".", "a/..", "./"):
            with self.subTest(s=s), self.assertRaises(ValueError):
                resolve_upload(self.root, s)

    def test_traversal_rejected(self):
        for s in ("../x", "a/../../x", "../root-sibling/secret.txt"):
            with self.subTest(s=s), self.assertRaises(ValueError):
                resolve_upload(self.root, s)

    def test_empty_and_nul_rejected(self):
        for s in ("", "a\0b"):
            with self.subTest(s=s), self.assertRaises(ValueError):
                resolve_upload(self.root, s)

    @unittest.skipUnless(hasattr(os, "symlink"), "needs symlinks")
    def test_symlink_to_sibling_rejected(self):
        os.symlink(self.sibling, self.root / "link")
        for s in ("link", "link/secret.txt", "link/new.txt"):
            with self.subTest(s=s), self.assertRaises(ValueError):
                resolve_upload(self.root, s)

    @unittest.skipUnless(hasattr(os, "symlink"), "needs symlinks")
    def test_symlink_inside_root_allowed(self):
        (self.root / "real").mkdir()
        os.symlink(self.root / "real", self.root / "alias")
        self.assertEqual(
            resolve_upload(self.root, "alias/f.txt"), self.root / "real" / "f.txt"
        )


if __name__ == "__main__":
    unittest.main()

from pathlib import Path, PurePosixPath, PureWindowsPath


def resolve_upload(root, supplied):
    """Resolve an untrusted relative path strictly inside root.

    Raises ValueError for absolute paths, empty/root-equal targets, NUL bytes,
    and anything that resolves (following existing symlinks) outside root.
    The target file need not exist. Nothing is created.
    """
    if not isinstance(supplied, str):
        raise ValueError("path must be a string")
    if not supplied or "\0" in supplied:
        raise ValueError("invalid path")
    if (
        PurePosixPath(supplied).is_absolute()
        or PureWindowsPath(supplied).is_absolute()
        or PureWindowsPath(supplied).drive
        or supplied.startswith(("/", "\\"))
    ):
        raise ValueError("absolute paths are not allowed")

    base = Path(root).resolve(strict=True)
    if not base.is_dir():
        raise ValueError("root is not a directory")

    try:
        target = (base / supplied).resolve(strict=False)
    except (OSError, RuntimeError) as exc:  # e.g. symlink loops
        raise ValueError("cannot resolve path") from exc

    if target == base:
        raise ValueError("target must not be the root")
    if not target.is_relative_to(base):
        raise ValueError("path escapes root")
    return target

import os
import sys
import tempfile
import unittest
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parent.parent / "src"))
from solution import resolve_upload


class ResolveUploadTests(unittest.TestCase):
    def setUp(self):
        self._tmp = tempfile.TemporaryDirectory()
        self.addCleanup(self._tmp.cleanup)
        self.tmp = Path(self._tmp.name).resolve()
        self.root = self.tmp / "root"
        self.sibling = self.tmp / "root_sibling"  # shares name prefix with root
        self.root.mkdir()
        self.sibling.mkdir()

    def test_simple_and_nested_nonexistent(self):
        self.assertEqual(resolve_upload(self.root, "a.txt"), self.root / "a.txt")
        self.assertEqual(resolve_upload(self.root, "x/y/z.txt"), self.root / "x/y/z.txt")
        self.assertFalse((self.root / "x").exists())  # nothing created

    def test_inner_dotdot_ok(self):
        self.assertEqual(resolve_upload(self.root, "a/../b.txt"), self.root / "b.txt")

    def test_rejects_absolute(self):
        with self.assertRaises(ValueError):
            resolve_upload(self.root, str(self.root / "a.txt"))

    def test_rejects_root_itself(self):
        for s in ("", ".", "a/..", "./"):
            with self.assertRaises(ValueError, msg=s):
                resolve_upload(self.root, s)

    def test_rejects_traversal(self):
        for s in ("../x", "a/../../x", "../root_sibling/f"):
            with self.assertRaises(ValueError, msg=s):
                resolve_upload(self.root, s)

    def test_rejects_sibling_prefix(self):
        with self.assertRaises(ValueError):
            resolve_upload(self.root, "../root_sibling/f.txt")

    @unittest.skipUnless(hasattr(os, "symlink"), "needs symlinks")
    def test_symlink_outside_rejected(self):
        os.symlink(self.sibling, self.root / "link")
        with self.assertRaises(ValueError):
            resolve_upload(self.root, "link/f.txt")
        with self.assertRaises(ValueError):
